SourceCode.Declaration:
class TFMPostResponseData extends TFMResponseElement
{

    Map                         printOutput;
    TFMRegistrationCollectors   regCols;
    Map	                        fields;

}

Method.Source:
public static TFMPostResponseData Construct()
{
    return new TFMPostResponseData();
}

protected void new()
{
    printOutput = new Map (Types::String, Types::String);
    fields = new Map(Types::String, Types::String);
    regCols = TFMRegistrationCollectors::Construct();
}

public void addPrintOutput(str _printerAddress, str _printCommand)
{        
    printOutput.insert(_printerAddress, (printOutput.exists(_printerAddress) ? printOutput.lookup(_printerAddress) : '') + _printCommand);
}

public str getFieldValue(str _key)
{
    return fields.exists(_key) ? fields.lookup(_key) : '';
}

public void appendToXml(XmlElement _element)
{
    XmlElement					registrationCollectorConfigurationElement;
    MapEnumerator				mEnum;
    if (regCols && regCols.collectorMap().elements())
    {
        registrationCollectorConfigurationElement = _element.ownerDocument().createElement(TFMConstants::registrationCollectorConfiguration());
        TFMRegistrationConfigurationResponseElement::appendRegistrationCollectorsToXML(registrationCollectorConfigurationElement, regCols);
        _element.appendChild(registrationCollectorConfigurationElement);
    }


    mEnum = printOutput.getEnumerator();
    while (mEnum.moveNext())
    {
        this.appendPrintToXML(_element, mEnum.currentKey(), mEnum.currentValue());
    }
}

protected void appendPrintToXML(XmlElement _element, str _printerAddress, str _printCommand)
{
    XmlElement  PrintElement          = _element.ownerDocument().createElement('print');
    XmlElement  PrintTypeElement      = _element.ownerDocument().createElement('printerType');
    XmlElement  PrintAddressElement   = _element.ownerDocument().createElement('printerAddress');
    XmlElement  PrintCommandElement   = _element.ownerDocument().createElement('printCommand');

    PrintTypeElement.innerText('Zebra');
    PrintAddressElement.innerText(_printerAddress);
    PrintCommandElement.innerText(_printCommand);
    PrintElement.appendChild(PrintTypeElement);
    PrintElement.appendChild(PrintAddressElement);
    PrintElement.appendChild(PrintCommandElement);
    _element.appendChild(PrintElement);

}
